"}, {"id": "3f2579ec-c682-4440-aa3d-d01e341aeb2f", "type": "concept", "title": "Trauma and social determinants"}], "description": "This subtopic introduces major ways of understanding addiction."}, {"id": "67ee3a3a-d497-43e7-a7ce-f0a4dd2b4838", "type": "subtopic", "title": "Behavioral addictions", "children": [{"id": "8d6ccfb2-4736-45d4-a464-910c4c907946", "type": "concept", "title": "Gambling disorder"}, {"id": "a89ba288-a8fb-41fe-9100-6ddcfedfc495", "type": "concept", "title": "Gaming and digital behavior concerns"}, {"id": "7a801996-5db3-42ee-987d-9e64b2cd83d8", "type": "concept", "title": "Shame and secrecy"}, {"id": "9d8291ca-134d-40cc-a7a4-2a2e7f7c52dd", "type": "concept", "title": "Referral and support options"}], "description": "Students learn emerging and established concerns such as gambling and compulsive behaviors."}]}, {"id": "40a38f7e-5d6d-4c61-a0ef-75ac7b2d3d2c", "type": "topic", "title": "Co-Occurring Disorders and Integrated Behavioral Health", "description": "Recognize co-occurring mental health and substance use concerns and integrated-care responses.", "children": [{"id": "4debff8d-0115-49ba-97ed-0e097678da43", "type": "subtopic", "title": "Co-occurring patterns", "children": [{"id": "f4c8e6ab-3c93-42d1-8112-cb30f2847491", "type": "concept", "title": "Depression and alcohol use"}, {"id": "29106d10-6551-4b31-bc3b-b20c23b506ea", "type": "concept", "title": "Trauma and substance use"}, {"id": "fd43d884-3cc7-433e-93aa-35643351d8b8", "type": "concept", "title": "Psychosis and substance use"}, {"id": "0249fb77-7cd0-4fe2-b70c-a6ec1a3cf3ca", "type": "concept", "title": "Anxiety and sedative or cannabis use"}], "description": "Mental health and substance use concerns often affect each other."}, {"id": "efb3744c-626a-4a92-afbc-33ee08a201a4", "type": "subtopic", "title": "Integrated care logic", "children": [{"id": "baa462c5-5a1f-410e-8b51-b817acd80629", "type": "concept", "title": "Single coordinated plan"}, {"id": "450a8efe-9cbc-4ee9-bbf7-c2547216cacf", "