update public.learning_paths
set
  title = 'Mental Health / Behavioral Health',
  goal = 'Mental Health / Behavioral Health',
  summary = 'This undergraduate Social Work elective introduces behavioral health systems, mental health and substance use concerns, DSM-informed language, trauma-informed care, crisis response, evidence-based treatment pathways, recovery, and coordinated supports through a person-in-environment and social justice lens.',
  data = $mhbhjson${"slug": "mental-health-behavioral-health", "title": "Mental Health / Behavioral Health", "description": "This undergraduate Social Work elective introduces behavioral health systems, mental health and substance use concerns, DSM-informed language, trauma-informed care, crisis response, evidence-based treatment pathways, recovery, and coordinated supports through a person-in-environment and social justice lens.", "topics": [{"id": "2417f29e-00c4-4be5-ac33-fea5ceb93617", "type": "topic", "title": "Behavioral Health Systems and the Social Work Role", "description": "Understand mental health systems, behavioral health service settings, and social work's person-in-environment role.", "children": [{"id": "582af6b0-9690-48bf-a3f7-34ab84659164", "type": "subtopic", "title": "Behavioral health system overview", "children": [{"id": "fe8ad43a-f77f-4826-a077-a1984ec11d57", "type": "concept", "title": "Community mental health centers"}, {"id": "5ecfe216-8338-4b69-a22c-9c13dd39717e", "type": "concept", "title": "Primary care and integrated care"}, {"id": "a07a2ee2-9138-4e03-9ce5-c39f5c9c4eb4", "type": "concept", "title": "Inpatient, outpatient, crisis, residential, and peer-led settings"}, {"id": "cff0304d-2749-45c3-bf3f-6dc36bf88c3c", "type": "concept", "title": "Access, insurance, waitlists, and service gaps"}], "description": "This subtopic orients students to the places where people seek help and the fragmented systems they often navigate."}, {"id": "b0822d0e-f128-4bbc-aee7-0fdcaf7ab6f8", "type": "subtopic", "title": "Social work role and scope", "children": [{"id": "debf49fa-fb03-4b25-8457-4d9b09aeab41", "type": "concept", "title": "Case management and care coordination"}, {"id": "296c710f-5831-44fb-b98e-3ef610584c57", "type": "concept", "title": "Clinical support and psychoeducation"}, {"id": "7d0a5d3d-64bb-42c2-9ae5-44e5edd972b8", "type": "concept", "title": "Advocacy and rights protection"}, {"id": "db944145-3dd3-46fa-b9bc-c28cc55bc830", "type": "concept", "title": "Supervision, referral, and scope limits"}], "description": "Students learn what social workers contribute to behavioral health through assessment, advocacy, coordination, and person-in-environment practice."}, {"id": "34197df2-699e-42c8-9743-391de8a7f271", "type": "subtopic", "title": "Person-in-environment lens", "children": [{"id": "d3d72cbb-fd02-4357-a0e9-049b5fa7f050", "type": "concept", "title": "Family, school, work, housing, legal, and community context"}, {"id": "40ccdf73-4b39-46f8-9c97-ac035fdd8f8a", "type": "concept", "title": "Strengths and protective factors"}, {"id": "2a6f3cca-a211-4d1f-ba08-dc812b2993dc", "type": "concept", "title": "Social determinants of mental health"}, {"id": "ca1fd9fa-07d8-4029-8e70-06062fa26f39", "type": "concept", "title": "Environmental stressors and supports"}], "description": "The point is to connect symptoms to context without reducing people to diagnoses."}]}, {"id": "88c068a5-1530-41f9-8cc3-1c6ce7e6772b", "type": "topic", "title": "Stigma, Social Determinants, Equity, and Mental Health", "description": "Examine how structural inequity, stigma, culture, and social determinants shape behavioral health.", "children": [{"id": "abd6fa16-35ed-402f-a505-db439106c94a", "type": "subtopic", "title": "Stigma and public attitudes", "children": [{"id": "99a012f5-b720-4af0-9f4c-dea820b11e49", "type": "concept", "title": "Public stigma"}, {"id": "e26b9dce-1ff3-4c8d-bacb-30a8471f0079", "type": "concept", "title": "Self-stigma"}, {"id": "01726451-0b54-4108-9226-4c93959a2c45", "type": "concept", "title": "Structural stigma"}, {"id": "2066e18f-5f02-45dc-83af-e3070ef2854c", "type": "concept", "title": "Language and recovery-oriented framing"}], "description": "Stigma shapes whether people seek care, disclose concerns, or receive respectful services."}, {"id": "19820e48-ac76-46d7-a05e-9a21e7ee811b", "type": "subtopic", "title": "Social determinants of behavioral health", "children": [{"id": "3492194e-f16c-4b60-b2ee-58c05a371676"